local PetData = {
	{Name = "Neon Bunny", Rarity = "Common", Chance = 70, Color = Color3.fromRGB(200, 200, 200)},
	{Name = "Cyber Cat", Rarity = "Uncommon", Chance = 20, Color = Color3.fromRGB(0, 255, 255)},
	{Name = "Plasma Dog", Rarity = "Rare", Chance = 8, Color = Color3.fromRGB(255, 0, 255)},
	{Name = "Glow Dragon", Rarity = "Legendary", Chance = 2, Color = Color3.fromRGB(255, 255, 0)}
}

return PetData

local MarketplaceService = game:GetService("MarketplaceService")
local Players = game:GetService("Players")
local ServerScriptService = game:GetService("ServerScriptService")

local ServiceFramework = require(ServerScriptService:WaitForChild("ServiceFramework"))

local MonetizationService = {}

local GAMEPASS_IDS = {
	VIP = 1234567, -- Placeholder
	DoubleCandy = 7654321 -- Placeholder
}

function MonetizationService:Init()
	MarketplaceService.PromptGamePassPurchaseFinished:Connect(function(player, passId, purchased)
		if purchased then
			print("[Monetization] Player " .. player.Name .. " bought gamepass " .. passId)
			-- Apply immediate benefits
		end
	end)
end

function MonetizationService:PlayerHasPass(player, passName)
	local passId = GAMEPASS_IDS[passName]
	if not passId then return false end

	local success, hasPass = pcall(function()
		return MarketplaceService:UserOwnsGamePassAsync(player.UserId, passId)
	end)

	return success and hasPass
end

return MonetizationService

